export default class l{static getLargestFileSize(t){let e=0;for(let i=0;i<t.files.length;i++){let s=t.files[i];s.size>e&&(e=s.size)}return e}static isFileExtensionInList(t,e){return e.indexOf("."+t)!==-1}static getExtensionFromFileName(t){return t.split(".").pop().toLowerCase()}static getUriWithoutGetParam(t){return t.split("?")[0]}static getRandomString(t){let e="";const i="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";for(let s=0;s<t;s++)e+=i.charAt(Math.floor(Math.random()*i.length));return e}static redirectToUri(t){t.indexOf("http")!==-1?window.location=t:window.location.pathname=t}static hideElement(t){t!==null&&(t.style.display="none")}static showElement(t){t!==null&&(t.style.display="block")}static isElementVisible(t){return t.offsetParent!==null}}
